plugins.faustDsp:
// Wavetable — single-cycle frames of 2048 samples, end to end in the node's `Table` file. The note
// reads one frame, Position morphs between neighbours, then a resonant low-pass and an ADSR.
// `freq`, `gain` and `gate` are the voice allocator's, never knobs (engine/k7-runtime/docs/faust.md).
import("stdfaust.lib");

freq = hslider("freq", 440, 20, 20000, 0.01);
gain = hslider("gain", 0.5, 0, 1, 0.01);
gate = button("gate");

position = hslider("Position", 0, 0, 1, 0.001) : si.smoo;
cutoff = hslider("Cutoff", 8000, 40, 20000, 1) : si.smoo;
resonance = hslider("Resonance", 1, 0.5, 10, 0.01);
attack = hslider("Attack", 0.01, 0.001, 4, 0.001);
decay = hslider("Decay", 0.3, 0.001, 4, 0.001);
sustain = hslider("Sustain", 0.7, 0, 1, 0.01);
release = hslider("Release", 0.4, 0.001, 8, 0.001);
glide = hslider("Glide", 0, 0, 2, 0.001);

table = soundfile("Table", 1);
N = 2048;

// How many frames the file holds: its length, read off the soundfile's first output.
frames = max(1, int(((0, 0) : table : _, !, !) / N));

// The pitch slides to each new note over Glide seconds, in log frequency so it moves evenly in pitch; 0 is a jump.
pitch = freq : log : si.smooth(ba.tau2pole(glide)) : exp;

// The read point inside one frame, and its neighbour for the linear interpolation.
ph = os.phasor(N, pitch);
i0 = int(ph);
fr = ph - i0;
i1 = (i0 + 1) % N;

// The two frames Position falls between.
fpos = position * (frames - 1);
f0 = int(fpos);
ff = fpos - f0;
f1 = min(f0 + 1, frames - 1);

read(f, i) = (0, f * N + i) : table : !, !, _;
sample(f) = read(f, i0) * (1 - fr) + read(f, i1) * fr;
osc = sample(f0) * (1 - ff) + sample(f1) * ff;

envelope = en.adsr(attack, decay, sustain, release, gate);
// Half scale: every frame is normalised to full, and a chord's voices add up.
process = osc * 0.5 : fi.resonlp(min(cutoff, ma.SR * 0.45), resonance, 1) : *(envelope * gain);

// dsp.dsp — le passe-bas en échelle de Moog, en Faust. La source que le moteur compile :
// deux réglages, un filtre par canal, et rien d'autre. Voir module.k7x à côté, et
// packages/song/docs/faustModules.md pour ce que le moteur en fait.

import("stdfaust.lib");

// `si.smoo` lisse le saut d'un potard entre deux blocs — le zipper que `glide` évite côté
// @studio/dsp, ici en une seule fonction de la bibliothèque standard.
cutoff = hslider("Cutoff", 1200, 20, 20000, 1) : si.smoo;
res    = hslider("Res", 0.3, 0, 0.95, 0.01) : si.smoo;

// Deux instances plutôt qu'une : un module est stéréo, et les deux voies ne partagent aucun
// état. C'est ce que `par` dit, et c'est aussi ce que le moteur attend d'un module audio.
process = par(i, 2, ve.moog_vcf(res, cutoff));

ui.script:
// wavetable — the table drawn as it is played: every frame stacked behind, and in front the frame
// Position is reading, morphed between its two neighbours exactly as dsp.dsp morphs them.

const N = 2048;

export default {
  wave(lcd) {
    const { ctx, width: W, height: H, params, color } = lcd;
    const pcm = lcd.sound("Table");
    if (!pcm || pcm.length < N) {
      ctx.fillStyle = color.dim;
      ctx.font = "9px ui-monospace, monospace";
      ctx.fillText(pcm ? "no 2048-sample frame in the table" : "loading table…", 6, H / 2);
      return;
    }
    const frames = Math.floor(pcm.length / N);
    const pos = Math.min(1, Math.max(0, params.Position ?? 0)) * (frames - 1);
    const pad = 4;
    // Each frame a little higher and to the right: a stack read back to front.
    const depthX = Math.min(24, W * 0.12);
    const depthY = Math.min(18, H * 0.25);
    const w = W - pad * 2 - depthX;
    const h = H - pad * 2 - depthY;
    const path = (sample, ox, oy) => {
      ctx.beginPath();
      const step = Math.max(1, Math.floor(N / w));
      for (let i = 0; i < N; i += step) {
        const x = pad + ox + (i / N) * w;
        const y = pad + oy + h / 2 - sample(i) * (h / 2) * 0.9;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    };
    const depth = (f) => (frames > 1 ? f / (frames - 1) : 0);
    for (let f = frames - 1; f >= 0; f--) {
      const d = depth(f);
      ctx.strokeStyle = color.dim;
      ctx.globalAlpha = 0.25 + 0.35 * (1 - Math.abs(f - pos) / Math.max(1, frames));
      ctx.lineWidth = 1;
      path((i) => pcm[f * N + i], d * depthX, depthY - d * depthY);
    }
    // The frame being played, in front: the same linear morph the program makes.
    const f0 = Math.floor(pos);
    const f1 = Math.min(f0 + 1, frames - 1);
    const t = pos - f0;
    const d = depth(pos);
    ctx.globalAlpha = 1;
    ctx.strokeStyle = color.ink;
    ctx.lineWidth = 1.5;
    ctx.shadowColor = color.glow;
    ctx.shadowBlur = 4;
    path((i) => pcm[f0 * N + i] * (1 - t) + pcm[f1 * N + i] * t, d * depthX, depthY - d * depthY);
    ctx.shadowBlur = 0;
    ctx.fillStyle = color.dim;
    ctx.font = "8px ui-monospace, monospace";
    ctx.fillText(`${(pos + 1).toFixed(1)} / ${frames}`, W - 44, H - 4);
  },
};

// moogladder — the ladder's 24 dB/octave response and its resonant peak.

const FONT = "8px ui-monospace, monospace";
const BLUE = "#3d7dff";
const GREEN = "#3ec96b";
const ORANGE = "#ff6a1a";
const GREY = "#6b6b6b";
const WHITE = "#ffffff";
const F_LO = 20;
const F_HI = 20000;

const num = (v, d) => (typeof v === "number" && Number.isFinite(v) ? v : d);
const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
const hz = (f) => (f >= 1000 ? `${(f / 1000).toFixed(f >= 10000 ? 0 : 1)}K` : `${Math.round(f)}`);

// dB of the analog section (b0 s^2 + b1 s + b2) / (a0 s^2 + a1 s + a2) at s = jx.
function sect(b, a, x) {
  const nr = b[2] - b[0] * x * x;
  const ni = b[1] * x;
  const dr = a[2] - a[0] * x * x;
  const di = a[1] * x;
  const n = Math.max(1e-30, nr * nr + ni * ni);
  const d = Math.max(1e-30, dr * dr + di * di);
  return 10 * Math.log10(n / d);
}

const LP = (q) => [[0, 0, 1], [1, 1 / Math.max(0.01, q), 1]];
const HP = (q) => [[1, 0, 0], [1, 1 / Math.max(0.01, q), 1]];
const BP = (q) => [[0, 1 / Math.max(0.01, q), 0], [1, 1 / Math.max(0.01, q), 1]];
const NOTCH = (q) => [[1, 0, 1], [1, 1 / Math.max(0.01, q), 1]];

// dB of one second-order shape at frequency f for a corner fc.
const shape = (s, f, fc) => sect(s[0], s[1], f / Math.max(1e-6, fc));

function glass(ctx, W, H) {
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, W, H);
  ctx.font = FONT;
  ctx.lineWidth = 1;
}

const frame = (W, H) => ({ x: 6, y: 13, w: Math.max(1, W - 12), h: Math.max(1, H - 19) });
const xOf = (b, f) => b.x + (Math.log(clamp(f, F_LO, F_HI) / F_LO) / Math.log(F_HI / F_LO)) * b.w;
const fOf = (b, px) => F_LO * (F_HI / F_LO) ** ((px - b.x) / Math.max(1, b.w));
const yOf = (b, db, lo, hi) => b.y + (1 - (clamp(db, lo, hi) - lo) / Math.max(1e-6, hi - lo)) * b.h;

// The 0 dB line and a tick at 100 Hz, 1 kHz and 10 kHz.
function grid(ctx, b, lo, hi) {
  ctx.strokeStyle = GREY;
  ctx.beginPath();
  const y0 = Math.round(yOf(b, 0, lo, hi)) + 0.5;
  ctx.moveTo(b.x, y0);
  ctx.lineTo(b.x + b.w, y0);
  for (const f of [100, 1000, 10000]) {
    const x = Math.round(xOf(b, f)) + 0.5;
    ctx.moveTo(x, b.y + b.h - 3);
    ctx.lineTo(x, b.y + b.h);
  }
  ctx.stroke();
}

function curve(ctx, b, dbAt, lo, hi, color) {
  ctx.strokeStyle = color;
  ctx.beginPath();
  for (let px = b.x; px <= b.x + b.w; px++) {
    const y = yOf(b, dbAt(fOf(b, px)), lo, hi);
    if (px === b.x) ctx.moveTo(px, y);
    else ctx.lineTo(px, y);
  }
  ctx.stroke();
}

function dot(ctx, x, y, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(x, y, 2.5, 0, Math.PI * 2);
  ctx.fill();
}

function text(ctx, s, x, y, color, align) {
  ctx.fillStyle = color;
  ctx.textAlign = align;
  ctx.fillText(s, x, y);
}

// dB of the four-pole ladder 1 / ((1 + s)^4 + k), normalised to 0 dB at DC.
function ladder(x, k) {
  const r2 = 1 - x * x;
  const i2 = 2 * x;
  const re = r2 * r2 - i2 * i2 + k;
  const im = 2 * r2 * i2;
  return 20 * Math.log10((1 + k) / Math.max(1e-15, Math.hypot(re, im)));
}

export default {
  response(lcd) {
    const { ctx, width: W, height: H, params } = lcd;
    glass(ctx, W, H);
    const b = frame(W, H);
    const fc = clamp(num(params["Cutoff"], 1200), 20, 20000);
    const res = clamp(num(params["Res"], 0.3), 0, 0.95);
    const k = 4 * res;
    grid(ctx, b, -36, 18);
    curve(ctx, b, (f) => ladder(f / fc, k), -36, 18, BLUE);
    dot(ctx, xOf(b, fc), yOf(b, ladder(1, k), -36, 18), ORANGE);
    text(ctx, "LADDER 24DB", b.x, 9, GREY, "left");
    text(ctx, `RES ${Math.round(res * 100)}`, W - 6, 9, ORANGE, "right");
    text(ctx, `${hz(fc)} HZ`, W - 56, 9, BLUE, "right");
  },
};
